import { Composio } from "@composio/core";
import { EveProvider } from "./eve-provider/index.js";

// Single shared Composio client. Import this everywhere instead of calling
// `new Composio(...)` per file. The EveProvider makes `session.tools()` hand
// back eve-native `defineTool`s.
export const composio = new Composio({
  apiKey: process.env.COMPOSIO_API_KEY,
  provider: new EveProvider(),
});

import { composio } from "./client.js";
import { createImessageToolkit } from "./imessage.js";

export const composioSession = composio.create(process.env.COMPOSIO_USER_ID!, {
  workbench: { enable: false },
  experimental: { customToolkits: [createImessageToolkit()] },
});

import { experimental_createToolkit } from "@composio/core";
import { findContact } from "./find-contact.js";
import { recallContact, rememberContact } from "./memory-tools.js";
import { readMessages } from "./read-messages.js";
import { sendMessage } from "./send-message.js";

// A self-contained Composio custom toolkit for local iMessage on macOS:
// send, find contacts, read messages, and per-contact memory. Framework-agnostic
export function createImessageToolkit() {
  return experimental_createToolkit("IMESSAGE", {
    name: "iMessage",
    description:
      "Send and read iMessages, look up contacts, and remember things about them, locally on the user's Mac.",
    tools: [sendMessage, findContact, readMessages, recallContact, rememberContact],
  });
}

import { experimental_createTool } from "@composio/core";
import { z } from "zod/v3";
import { runAppleScript } from "./applescript.js";

const SEND_SCRIPT = `on run {targetBuddy, targetText}
	tell application "Messages"
		set targetService to 1st service whose service type = iMessage
		send targetText to buddy targetBuddy of targetService
	end tell
end run`;

// "Think" time + time to type the message, with jitter, capped — so messages
// don't fire instantly.
function humanDelayMs(text: string): number {
  const think = 800 + Math.random() * 1700; // 0.8–2.5s
  const typing = text.length * (40 + Math.random() * 40); // ~40–80ms/char
  return Math.min(think + typing, 12_000);
}

export const sendMessage = experimental_createTool("SEND", {
  name: "Send iMessage",
  description:
    "Send an iMessage from the user's Mac to a phone number or iMessage email handle.",
  preload: true,
  inputParams: z.object({
    to: z
      .string()
      .describe("Recipient handle: phone number (e.g. +15551234567) or iMessage email."),
    text: z.string().describe("Message body to send."),
    name: z.string().optional().describe("Recipient's contact name, for display."),
  }),
  execute: async ({ to, text }) => {
    await new Promise((r) => setTimeout(r, humanDelayMs(text)));
    await runAppleScript(SEND_SCRIPT, [to, text]);
    return { sent: true, to };
  },
});

import {
  BaseAgenticProvider,
  type ExecuteToolFn,
  type McpServerGetResponse,
  type McpUrlResponse,
  normalizeToolArguments,
  removeNonRequiredProperties,
  type Tool,
  type ToolExecuteResponse,
} from "@composio/core";
import type { JsonValue } from "eve/connections";
import { type ToolDefinition, defineTool } from "eve/tools";
import { applyHooks, type EveProviderHooks } from "./hooks.js";

export type EveTool = ToolDefinition<Record<string, unknown>, ToolExecuteResponse>;
export type EveToolCollection = Record<string, EveTool>;

export interface EveProviderOptions {
  strict?: boolean;
  hooks?: EveProviderHooks;
}

export class EveProvider extends BaseAgenticProvider<
  EveToolCollection,
  EveTool,
  McpServerGetResponse
> {
  readonly name = "eve";

  constructor(private readonly options: EveProviderOptions = {}) {
    super();
  }

  wrapTool(tool: Tool, executeTool: ExecuteToolFn): EveTool {
    const params = tool.inputParameters;
    const inputSchema =
      this.options.strict && params?.type === "object"
        ? removeNonRequiredProperties(params)
        : (params ?? { type: "object", properties: {} });

    return defineTool({
      description: tool.description ?? tool.name,
      inputSchema: inputSchema as Record<string, JsonValue>,
      execute: (input) =>
        applyHooks(
          this.options.hooks ?? {},
          tool.slug,
          normalizeToolArguments(input, tool.slug),
          executeTool,
        ),
    });
  }

  wrapTools(tools: Tool[], executeTool: ExecuteToolFn): EveToolCollection {
    return Object.fromEntries(tools.map((tool) => [tool.slug, this.wrapTool(tool, executeTool)]));
  }

  wrapMcpServerResponse(data: McpUrlResponse): McpServerGetResponse {
    return data.map((item) => ({ url: new URL(item.url), name: item.name })) as McpServerGetResponse;
  }
}

import { defineDynamic } from "eve/tools";
import type { EveToolCollection } from "./provider.js";

type EveSession = { tools: () => Promise<EveToolCollection> };

// step.started keeps the provider's live execute closures (session.started
// snapshots them away); cached since session.tools() is a network call.
export function defineComposioTools<S extends EveSession>(session: S | Promise<S>) {
  let cache: Promise<EveToolCollection> | undefined;
  return defineDynamic({
    events: {
      "step.started": () => (cache ??= Promise.resolve(session).then((s) => s.tools())),
    },
  });
}

import type { ExecuteToolFn, ToolExecuteResponse } from "@composio/core";

type MaybePromise<T> = T | Promise<T>;
type Next = () => Promise<ToolExecuteResponse>;

export interface EveHookControls {
  deny(reason: string): ToolExecuteResponse;
}

export interface EveHookContext extends EveHookControls {
  request: { slug: string; args: Record<string, unknown> };
  readonly context: { readonly slug: string };
}

export interface EveAuthLinkContext extends EveHookControls {
  readonly url: string;
  readonly result: ToolExecuteResponse;
}

export type EveHook = (ctx: EveHookContext, next: Next) => MaybePromise<ToolExecuteResponse | void>;
export type EveAuthLinkHook = (
  ctx: EveAuthLinkContext,
  next: Next,
) => MaybePromise<ToolExecuteResponse | void>;

export interface EveProviderHooks {
  search?: EveHook;
  manageConnections?: EveHook;
  execute?: EveHook;
  remoteWorkbench?: EveHook;
  remoteBash?: EveHook;
  onAuthLink?: EveAuthLinkHook;
}

export const denyEveToolCall = (reason: string): ToolExecuteResponse => ({
  data: {},
  error: reason,
  successful: false,
});

const HOOK_BY_SLUG = {
  COMPOSIO_SEARCH_TOOLS: "search",
  COMPOSIO_MANAGE_CONNECTIONS: "manageConnections",
  COMPOSIO_MULTI_EXECUTE_TOOL: "execute",
  COMPOSIO_EXECUTE_TOOL: "execute",
  COMPOSIO_REMOTE_WORKBENCH: "remoteWorkbench",
  COMPOSIO_REMOTE_BASH_TOOL: "remoteBash",
} as const;

type MetaSlug = keyof typeof HOOK_BY_SLUG;

const CONNECT_LINK = /https:\/\/connect\.composio\.dev\/[^\s<>)"']+/gi;
const GENERIC_LINK = /https:\/\/[^\s<>)"']*composio[^\s<>)"']*\/link\/[^\s<>)"']+/gi;

const extractAuthLinks = (result: ToolExecuteResponse): string[] => {
  const text = JSON.stringify(result.data ?? {});
  const links = [...(text.match(CONNECT_LINK) ?? []), ...(text.match(GENERIC_LINK) ?? [])];
  return [...new Set(links.map((url) => url.replace(/[.,;:!?]+$/g, "")))];
};

const runHook = async <C>(
  hook: ((ctx: C, next: Next) => MaybePromise<ToolExecuteResponse | void>) | undefined,
  ctx: C,
  getDefault: Next,
): Promise<ToolExecuteResponse> => {
  if (!hook) return getDefault();
  let pending: Promise<ToolExecuteResponse> | undefined;
  const next: Next = () => (pending ??= getDefault());
  return (await hook(ctx, next)) ?? pending ?? next();
};

export async function applyHooks(
  hooks: EveProviderHooks,
  slug: string,
  args: Record<string, unknown>,
  executeTool: ExecuteToolFn,
): Promise<ToolExecuteResponse> {
  const ctx: EveHookContext = { request: { slug, args }, context: { slug }, deny: denyEveToolCall };
  const name = HOOK_BY_SLUG[slug as MetaSlug] as (typeof HOOK_BY_SLUG)[MetaSlug] | undefined;
  const result = await runHook(name ? hooks[name] : undefined, ctx, () =>
    executeTool(ctx.request.slug, ctx.request.args),
  );

  const { onAuthLink } = hooks;
  if (!onAuthLink) return result;

  let current = result;
  for (const url of extractAuthLinks(result)) {
    const previous = current;
    current = await runHook(onAuthLink, { url, result: previous, deny: denyEveToolCall }, async () => previous);
  }
  return current;
}

